WFJ.Data.add("gossip", {
  ["8f01cab29786f703"] = { "La famiglia Carevin combatte per la vittoria sotto la Luce. Il mio dovere sotto la Luce è dare la vita nella loro battaglia contro i non morti. Il maestro Carevin mi ha affidato lo sterminio dei vili worgen di ⟦Duskwood=Boscovespro⟧. Forse vorresti aiutarmi?", "." },
  ["8f0243c434a845f8"] = { "Un esame sommario dei resti scheletrici indica che la carne è stata bruciata via. Uno spettacolo davvero raccapricciante.", "." },
  ["8f086793982122f2"] = { "Ho io la chiave delle terre dei liberi! Inseguimi e vedrai!", "." },
  ["8f0a52b0737d0a68"] = { "Ora credo nelle tue intenzioni, {name}, e ti ringrazio della disponibilità ad aiutare i membri della mia ex compagnia di mercenari, The Veiled Blade.\n\nVediamo, cosa c'è dopo nella nostra lista delle cose da fare?", "." },
  ["8f0e661d27d76e8d"] = { "%s si scheggia e va in frantumi!", "." },
  ["8f25666b27c77a48"] = { "Venite, venite tutti! Le merci di Antonio sono in vendita. Potrei non tornare per molto tempo, quindi venite, venite tutti!", "." },
  ["8f2c1ccc2fcb8cd9"] = { "Grazie per aver trovato i miei reagenti! *sbadiglio* Quel veleno mi ha fatto... venire un po' di sonno...", "." },
  ["8f312a64c92d9e2f"] = { "Che il vostro spirito si sollevi! Stringetevi attorno al vostro campione, crogiolatevi nella sua gloria! Esultate al grido di battaglia di chi ha ucciso il drago!", "." },
  ["8f34ce85bf9f3992"] = { "Impostore! Farsi evocare da un cucciolo come te è un disonore senza pari! MUORI!", "." },
  ["8f370e6205d8686a"] = { "La forza della tua determinazione risplende, {name}. Continui a dimostrare di essere una risorsa per il nostro popolo. Un giorno il mondo comprenderà la portata delle tue grandi imprese.", "." },
  ["8f3c6c6340a4a94c"] = { "Dove posso trovare dei Nuclei di Elementi?", "." },
  ["8f41c208ef8662e0"] = { "Ti serve qualcosa?", "." },
  ["8f42e1854e39a08c"] = { "è un blocco di ghiaccio!", "." },
  ["8f4562dfe2359063"] = { "%s va su tutte le furie dopo aver visto cadere {name} in battaglia!", "." },
  ["8f49d66ab62492fc"] = { "Basta torturarmi! Liberami, mortale! La ⟦Swamp of Sorrows=Palude del Dolore⟧... mortale... ti prego...", "." },
  ["8f4f2f0dfa39cecb"] = { "Sei <un/una> <figlio/figlia> della natura, eh? Allora non devi cercare oltre il pozzo lunare nel Parco.", "." },
  ["8f581c1c949bf01c"] = { "Oh, se solo avessi un ramo d'albero da tenere davanti a me. Le guardie non mi vedrebbero mai.", "." },
  ["8f5e6e12fe9beb59"] = { "Troviamo il prossimo, {name}.", "." },
  ["8f65a340e1ad506f"] = { "I miei occhi! Brucia... brucia...", "." },
  ["8f6829963976f24e"] = { "⟦Drek'Thar=Drek'thar⟧, sto venendo a prenderti!", "." },
  ["8f6a2d0c828fdc29"] = { "Tu non manca Armand Cromwell in ⟦Magic Quarter=Quartiere della Magia⟧. Lui sta su molo.", "." },
  ["8f6d7d7989b11970"] = { "Che non resti nemmeno una goccia del loro sangue sul pavimento dell'arena, figli miei. Banchettate con le loro anime!", "." },
  ["8f74d00fd5fe636c"] = { "Ho trovato entrambe le parti del tuo scettro.", "." },
  ["8f766ce518dfae6e"] = { "Ti serve l'insegnamento di un vero maestro! Va' da Daryl Stack al ⟦Tarren Mill=Mulino di Tarren⟧ e abbraccia il tuo destino!", "." },
  ["8f7db87927cad640"] = { "Oh, che stanchezza...", "." },
  ["8f8b1e880e79a8b2"] = { "Questo è un esemplare esotico di flora, mai visto in altre parti di Teldrassil.", "." },
  ["8f93f0a7bab7e9c8"] = { "È fatto. {name}, la tua armatura è pronta.", "." },
  ["8f9bfd05f2ebaf98"] = { "Hai interferito con i nostri piani per l'ultima volta, <stolto/stolta> {class}!", "." },
  ["8f9d6a7792da8584"] = { "Verrà il momento in cui potrai ricevere ciò che ho da insegnarti, {name}. Fino ad allora, chiedi a Darianna, laggiù, di aiutarti con l'addestramento.", "." },
  ["8fa52aedb997bf8a"] = { "Ho raggiunto il ⟦Crossroads=Crocevia⟧ da sud in cerca d'aiuto, {class}, ma trovo solo codardi che mi voltano le spalle... persino il potente Thork mi insulta così. È un buon capo, ma il suo rifiuto della mia supplica mi fa infuriare ancora di più.\n\nDice che la rabbia mi fa agire con troppa fretta, che mi offusca il giudizio... ma non avrò pace finché non avrò ottenuto vendetta!", "." },
  ["8fa7c0070c73e70c"] = { "Ohi... un paladino? Beh, <ragazzo/ragazza>, ti va bene! ⟦Azar Stronghammer=Azar Martelduro⟧ è tornato dall'addestramento e al momento alloggia alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ di Kharanos.", "." },
  ["8fb67d36e2e43164"] = { "Regali per tutti! Father Winter ha messo doni sotto l'albero per tutti.", "." },
  ["8fb7bd9376e50e9a"] = { "Una birra Thunderbrew e un po' della cucina di Gremlock fanno davvero un bel pasto. Dovresti proprio chiedergli un po' di addestramento, se vuoi imparare a cucinare.", "." },
  ["8fb7e5ca5e9107a3"] = { "Che cos'hai lì, amico?", "." },
  ["8fba3c8a9054257a"] = { "I tauren hanno la passione per la caccia: è qualcosa di profondamente radicato nella nostra gente.", "." },
  ["8fbe455101f1471f"] = { "Non c'è molto da pescare da queste parti, ma quel poco che c'è è di Paxton, puoi giurarci. Lo trovi a pescare sul ⟦Iceflow Lake=Lago di Ghiacciospesso⟧.", "." },
  ["8fc2f52ec3e0ec9a"] = { "Tragico. Il vecchio Fordring vive ancora... Arrivi troppo tardi, vecchio. Ritirati nella tua caverna, eremita, a meno che tu non voglia raggiungere tuo figlio nella ⟦Twisting Nether=Distorsione Fatua⟧.", "." },
  ["8fcf7b6936c95e2f"] = { "Resta vicino a me, {name}. Mi servirà tutto l'aiuto possibile per uscire di qui. Andiamo!", "." },
  ["8fd148b6bb3d0739"] = { "Mi serve un altro set di Strumenti dei Ladri.", "." },
  ["8fd57e1cba8336fe"] = { "Le mie forze e io siamo pronti. Mettiamo fine a questa messinscena!", "." },
  ["8fd63912ac50b32f"] = { "{name}, abbiamo abbastanza rifornimenti per lanciare assalti di terra. Se la tua reputazione presso la ⟦Stormpike Guard=Guardia dei Piccatonante⟧ è abbastanza alta, parla con il caporale Noreg Stormpike.", "." },
  ["8fdd728817b47e41"] = { "Sì, l'ho fatto. Insegnami.", "." },
  ["8fddcd20587941d8"] = { "Esistenza presunta. Solo una creatura draconica cromatica superiore o un drago potrebbe possedere un simile carapace.", "." },
  ["8fdee3ee9e3e0581"] = { "Concentrate i vostri attacchi sul guaritore!", "." },
  ["8fe3ad9fc61cdaab"] = { "Andammo avanti così per circa sei mesi, e osservammo la casa subire cambiamenti orribili. Mostri immondi vagavano liberi per il maniero. Oscuri cultisti ne occupavano ogni centimetro con vari oggetti legati a rituali e sacrifici. Sapevamo di non poterci nascondere ancora a lungo.\n\nCome previsto, fummo scoperti e catturati. Ci tolsero tutti i vestiti e ci stesero dentro un cerchio di sangue. Restammo lì per giorni, nudi e terrorizzati.", "." },
  ["8fe9e9e4ba9301f9"] = { "Hai qualche spicciolo?", "." },
  ["8feb33e3edff15d7"] = { "Uccidere...", "." },
  ["8ff4244abc413f38"] = { "Guarda! Guarda! Ho preso qualcosa! Ohhh... è solo un vecchio stivale puzzolente.", "." },
  ["8ff8fcc4253a9907"] = { "Dov'è il quartiermastro dei Piccatonante?", "." },
  ["8fffeeb8d464765b"] = { "⟦Elune's Candle=La Candela di Elune⟧ stordisce %s!", "." },
})
